CREATE TYPE invoice_status AS ENUM (\n  'RECEIVED','MATCHING','MATCHED','MISMATCH','PENDING_APPROVAL',\n  'APPROVED','REJECTED','PAID','CANCELLED');\nCREATE TYPE payment_status AS ENUM ('PENDING','EXECUTED','FAILED','COMPENSATED');\n\nCREATE TABLE purchase_order (\n  tenant_id  uuid NOT NULL,\n  po_id      uuid NOT NULL,\n  project_id uuid NOT NULL,\n  po_number  varchar(80) NOT NULL,\n  status     varchar(30) NOT NULL,\n  PRIMARY KEY (tenant_id, po_id)\n);\nCREATE TABLE purchase_order_line (\n  tenant_id   uuid NOT NULL,\n  po_line_id  uuid NOT NULL,\n  po_id       uuid NOT NULL,\n  line_number int NOT NULL,\n  description varchar(300) NOT NULL,\n  quantity    numeric(18,4) NOT NULL,\n  unit_price  numeric(18,4) NOT NULL,\n  PRIMARY KEY (tenant_id, po_line_id)\n);\nCREATE TABLE goods_receipt (\n  tenant_id   uuid NOT NULL,\n  receipt_id  uuid NOT NULL,\n  po_id       uuid NOT NULL,\n  received_at timestamptz NOT NULL,\n  received_by uuid NOT NULL,\n  PRIMARY KEY (tenant_id, receipt_id)\n);\nCREATE TABLE goods_receipt_line (\n  tenant_id         uuid NOT NULL,\n  receipt_line_id   uuid NOT NULL,\n  receipt_id        uuid NOT NULL,\n  po_line_id        uuid NOT NULL,\n  quantity_received numeric(18,4) NOT NULL,\n  PRIMARY KEY (tenant_id, receipt_line_id)\n);\n\nCREATE TABLE invoice (\n  tenant_id         uuid NOT NULL,\n  invoice_id        uuid NOT NULL,\n  project_id        uuid NOT NULL,\n  contract_id       uuid NOT NULL,\n  subcontractor_id  uuid NOT NULL,\n  invoice_number    varchar(80) NOT NULL,\n  amount            numeric(18,2) NOT NULL,\n  currency          char(3) NOT NULL,\n  invoice_date      date NOT NULL,\n  received_at       timestamptz NOT NULL,\n  status            invoice_status NOT NULL,\n  po_reference      varchar(80),\n  work_package_id   uuid,\n  aggregate_version bigint NOT NULL DEFAULT 1,\n  created_at        timestamptz NOT NULL DEFAULT now(),\n  updated_at        timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, invoice_id)\n);\nCREATE TABLE invoice_line (\n  tenant_id       uuid NOT NULL,\n  invoice_line_id uuid NOT NULL,\n  invoice_id      uuid NOT NULL,\n  line_number     int NOT NULL,\n  description     varchar(300) NOT NULL,\n  quantity        numeric(18,4) NOT NULL,\n  unit_price      numeric(18,4) NOT NULL,\n  PRIMARY KEY (tenant_id, invoice_line_id)\n);\n\nCREATE TABLE three_way_match_result (\n  tenant_id            uuid NOT NULL,\n  match_id             uuid NOT NULL,\n  invoice_id           uuid NOT NULL,\n  estado               varchar(30) NOT NULL,\n  tolerancia_aplicada  numeric(8,4) NOT NULL,\n  diferencias          jsonb NOT NULL,\n  event_id             uuid NOT NULL,\n  created_at           timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, match_id),\n  CHECK ((estado = 'MATCH' AND jsonb_array_length(diferencias) = 0)\n      OR (estado <> 'MATCH'))\n);\n\nCREATE TABLE payment_application (\n  tenant_id               uuid NOT NULL,\n  payment_application_id  uuid NOT NULL,\n  invoice_id              uuid NOT NULL,\n  project_id              uuid NOT NULL,\n  subcontractor_id        uuid NOT NULL,\n  amount_requested        numeric(18,2) NOT NULL,\n  amount_approved         numeric(18,2),\n  status                  varchar(30) NOT NULL,\n  match_id                uuid,\n  compliance_version_seen bigint,\n  approval_route          varchar(30),\n  aggregate_version       bigint NOT NULL DEFAULT 1,\n  created_at              timestamptz NOT NULL DEFAULT now(),\n  updated_at              timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, payment_application_id)\n);\n\nCREATE TABLE payment (\n  tenant_id               uuid NOT NULL,\n  payment_id              uuid NOT NULL,\n  invoice_id              uuid NOT NULL,\n  payment_application_id  uuid NOT NULL,\n  project_id              uuid NOT NULL,\n  subcontractor_id        uuid NOT NULL,\n  amount                  numeric(18,2) NOT NULL,\n  currency                char(3) NOT NULL,\n  executed_at             timestamptz,\n  status                  payment_status NOT NULL,\n  compliance_version_seen bigint,\n  compensation_case_id    uuid,\n  compensation_state      varchar(30) NOT NULL DEFAULT 'NONE',\n  aggregate_version       bigint NOT NULL DEFAULT 1,\n  created_at              timestamptz NOT NULL DEFAULT now(),\n  updated_at              timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, payment_id)\n);\n\nCREATE TABLE payment_read_model (\n  tenant_id               uuid NOT NULL,\n  payment_id              uuid NOT NULL,\n  invoice_id              uuid NOT NULL,\n  project_id              uuid NOT NULL,\n  subcontractor_id        uuid NOT NULL,\n  amount                  numeric(18,2) NOT NULL,\n  status                  payment_status NOT NULL,\n  executed_at             timestamptz,\n  compliance_version_seen bigint,\n  compensation_case_id    uuid,\n  compensation_state      varchar(30) NOT NULL DEFAULT 'NONE',\n  updated_at              timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, payment_id)\n);\n\nCREATE TYPE invalidity_type AS ENUM (\n  'DOCUMENTO_FRAUDULENTO',\n  'CERTIFICADO_VENCIDO_RETROACTIVO',\n  'ERROR_ADMINISTRATIVO',\n  'REVOCACION_POSTERIOR'\n);\nCREATE TABLE payment_invalidation (\n  tenant_id         uuid NOT NULL,\n  invalidation_id   uuid NOT NULL,\n  payment_id        uuid NOT NULL,\n  invalidity_type   invalidity_type NOT NULL,\n  evidence_id       uuid NOT NULL,\n  effective_date    date NOT NULL,\n  amount            numeric(18,2) NOT NULL,\n  contractual_basis text NOT NULL,\n  detected_by       uuid NOT NULL,\n  detected_at       timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, invalidation_id),\n  UNIQUE (tenant_id, payment_id, invalidity_type, evidence_id)\n);\n\nALTER TABLE purchase_order         ENABLE ROW LEVEL SECURITY;\nALTER TABLE purchase_order_line    ENABLE ROW LEVEL SECURITY;\nALTER TABLE goods_receipt          ENABLE ROW LEVEL SECURITY;\nALTER TABLE goods_receipt_line     ENABLE ROW LEVEL SECURITY;\nALTER TABLE invoice                ENABLE ROW LEVEL SECURITY;\nALTER TABLE invoice_line           ENABLE ROW LEVEL SECURITY;\nALTER TABLE three_way_match_result ENABLE ROW LEVEL SECURITY;\nALTER TABLE payment_application    ENABLE ROW LEVEL SECURITY;\nALTER TABLE payment                ENABLE ROW LEVEL SECURITY;\nALTER TABLE payment_read_model     ENABLE ROW LEVEL SECURITY;\nALTER TABLE payment_invalidation   ENABLE ROW LEVEL SECURITY;\n\nDO $$\nDECLARE t text;\nBEGIN\n  FOR t IN SELECT unnest(ARRAY[\n    'purchase_order','purchase_order_line','goods_receipt','goods_receipt_line',\n    'invoice','invoice_line','three_way_match_result','payment_application',\n    'payment','payment_read_model','payment_invalidation'\n  ]) LOOP\n    EXECUTE format('CREATE POLICY ti_%I ON %I USING (tenant_id = current_setting(''app.tenant_id'')::uuid)', t, t);\n  END LOOP;\nEND $$;